const { partnerId, privacyFor } = require('./creation_access');

// Upload filenames are generated by the server. Match the path that will
// actually be served, with no decoded aliases or arbitrary subdirectories.
const imagePath = /^\/uploads\/(?:(photos|avatars|creations|travel|kitchen|wardrobe(?:\/cutout)?)\/)?([A-Za-z0-9][A-Za-z0-9_.-]{0,159}\.(?:jpg|jpeg|png|webp|gif|heic|heif|bmp))$/i;

function parseMedia(value) {
  if (typeof value !== 'string') return null;
  const match = imagePath.exec(value);
  if (!match) return null;
  const embedded = /^u(\d+)_/.exec(match[2]);
  return { path: value, kind: match[1] || 'photos', ownerId: embedded ? Number(embedded[1]) : null };
}

async function ownerFor(pool, media) {
  if (media.ownerId != null) return media.ownerId;
  const [rows] = await pool.query('SELECT user_id, kind FROM legacy_media_owners WHERE path = ?', [media.path]);
  const row = rows[0];
  return row?.kind === media.kind ? Number(row.user_id) : null;
}

async function ownsMedia(pool, userId, value) {
  const media = parseMedia(value);
  return media != null && await ownerFor(pool, media) === Number(userId);
}

async function canAttachPhoto(pool, userId, value) {
  if (value == null || value === '') return true;
  if (typeof value !== 'string') return false;
  if (value.startsWith('/uploads/')) return ownsMedia(pool, userId, value);
  try {
    const uri = new URL(value);
    return ['http:', 'https:'].includes(uri.protocol) && !uri.pathname.startsWith('/uploads/');
  } catch (_) {
    return false;
  }
}

async function canReadMedia(pool, userId, media) {
  const owner = await ownerFor(pool, media);
  if (!owner) return false;
  if (owner === userId) return true;
  if (media.kind.startsWith('wardrobe') || await partnerId(pool, userId) !== owner) return false;
  const url = media.path;
  let records;
  switch (media.kind) {
    case 'photos':
      if (!(await privacyFor(pool, owner)).photo_visible) return false;
      [records] = await pool.query(
        "SELECT 1 FROM photos WHERE user_id = ? AND visibility = 'shared' AND (url = ? OR thumbnail_url = ?) LIMIT 1",
        [owner, url, url]
      );
      break;
    case 'avatars':
      [records] = await pool.query('SELECT 1 FROM users WHERE id = ? AND avatar_url = ?', [owner, url]);
      break;
    case 'creations':
      [records] = await pool.query(
        'SELECT 1 FROM creative_works WHERE user_id = ? AND deleted_at IS NULL AND (preview_url = ? OR JSON_CONTAINS(source_urls, JSON_QUOTE(?))) LIMIT 1',
        [owner, url, url]
      );
      break;
    case 'travel':
      if (!(await privacyFor(pool, owner)).travel_visible) return false;
      [records] = await pool.query(
        'SELECT 1 FROM travel_photos p JOIN travel_spots s ON s.id = p.spot_id WHERE p.user_id = ? AND p.url = ? AND s.user_id IN (?, ?) LIMIT 1',
        [owner, url, owner, userId]
      );
      break;
    case 'kitchen':
      [records] = await pool.query(
        `SELECT 1 FROM kitchen_dishes WHERE user_id = ? AND photo_url = ?
         UNION ALL SELECT 1 FROM cooking_logs WHERE chef_id = ? AND photo_url = ? AND kitchen_order_id IS NULL
         UNION ALL SELECT 1 FROM kitchen_orders WHERE cook_id = ? AND photo_url = ? AND (orderer_id = ? OR partner_id = ?)
         LIMIT 1`,
        [owner, url, owner, url, owner, url, userId, userId]
      );
      break;
    default:
      return false;
  }
  return records.length > 0;
}

function protectUploads(pool) {
  return async (req, res, next) => {
    res.set('Cache-Control', 'private, no-store');
    try {
      const media = parseMedia('/uploads' + req.path);
      const userId = Number(req.user.id);
      if (media && req.user.type !== 'refresh' && Number.isSafeInteger(userId) && userId > 0 &&
          await canReadMedia(pool, userId, media)) {
        return next();
      }
      return res.status(404).json({ code: 404, message: '文件不存在或不可访问' });
    } catch (error) {
      console.error('[Media]', error.code || error.name);
      return res.status(503).json({ code: 503, message: '暂时无法读取图片' });
    }
  };
}

module.exports = { parseMedia, ownsMedia, canAttachPhoto, protectUploads };
